int main(void) {
    int N, F;
    scanf("%d %d", &N, &F);

    char grid[505][505];
    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    if (grid[0][0] - '0' <= F) {
        int q[250005];
        int front = 0, back = 0;

        grid[0][0] = '*';
        q[back++] = 0;

        int dr[4] = {-1, 1, 0, 0};
        int dc[4] = {0, 0, -1, 1};

        while (front < back) {
            int idx = q[front++];
            int r = idx / N;
            int c = idx % N;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
                    if (grid[nr][nc] != '*' && grid[nr][nc] - '0' <= F) {
                        grid[nr][nc] = '*';
                        q[back++] = nr * N + nc;
                    }
                }
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
