    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    if (grid[0][0] - '0' <= F) {
        int head = 0, tail = 0;

        grid[0][0] = '*';
        queue[tail++] = 0;

        while (head < tail) {
            int cur = queue[head++];
            int r = cur / N;
            int c = cur % N;

            if (r > 0 && grid[r - 1][c] != '*' && grid[r - 1][c] - '0' <= F) {
                grid[r - 1][c] = '*';
                queue[tail++] = cur - N;
            }
            if (r + 1 < N && grid[r + 1][c] != '*' && grid[r + 1][c] - '0' <= F) {
                grid[r + 1][c] = '*';
                queue[tail++] = cur + N;
            }
            if (c > 0 && grid[r][c - 1] != '*' && grid[r][c - 1] - '0' <= F) {
                grid[r][c - 1] = '*';
                queue[tail++] = cur - 1;
            }
            if (c + 1 < N && grid[r][c + 1] != '*' && grid[r][c + 1] - '0' <= F) {
                grid[r][c + 1] = '*';
                queue[tail++] = cur + 1;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
